package io.invenlio.procurement;
import io.invenlio.catalog.CatalogInventoryLookup;import io.invenlio.organization.*;import java.math.*;import java.sql.*;import java.time.*;import java.util.*;import org.springframework.context.ApplicationEventPublisher;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class ProcurementService implements SupplierEligibilityQuery{private final AuthorizationService auth;private final AuditTrail audit;private final CatalogInventoryLookup catalog;private final JdbcTemplate db;private final ApplicationEventPublisher events;ProcurementService(AuthorizationService a,AuditTrail u,CatalogInventoryLookup c,JdbcTemplate d,ApplicationEventPublisher e){auth=a;audit=u;catalog=c;db=d;events=e;}
 @Transactional Supplier supplierCreate(SupplierCommand c){var a=manage();validateSupplier(c);UUID id=UUID.randomUUID();try{db.update("INSERT INTO suppliers(id,tenant_id,supplier_number,normalized_supplier_number,name,legal_name,status,tax_id,tax_country_code,registration_number,email,phone,website,default_currency,payment_terms_days,default_lead_time_days,notes,created_at,updated_at,version)VALUES(?,?,?,?,?,?,'DRAFT',?,?,?,?,?,?,?,?,?,?,now(),now(),0)",id,a.tenantId(),number(c.supplierNumber),number(c.supplierNumber),req(c.name,200),trim(c.legalName,200),trim(c.taxId,64),country(c.taxCountryCode),trim(c.registrationNumber,64),email(c.email),trim(c.phone,40),trim(c.website,500),currency(c.defaultCurrency),days(c.paymentTermsDays),days(c.defaultLeadTimeDays),trim(c.notes,2000));}catch(Exception e){throw conflict(e,"SUPPLIER_NUMBER_EXISTS","Supplier number exists");}audit.record(a,"SUPPLIER_CREATED","supplier",id.toString());events.publishEvent(new ProcurementEvents.SupplierCreated(a.tenantId(),id));return supplier(a.tenantId(),id);}
 @Transactional Supplier supplierUpdate(UUID id,SupplierCommand c,long version){var a=manage();Supplier old=supplier(a.tenantId(),id);validateSupplier(c);if(!old.status.equals("DRAFT")&&!old.supplierNumber.equals(number(c.supplierNumber)))throw err("SUPPLIER_NUMBER_IMMUTABLE","Supplier number is immutable after draft");int n=db.update("UPDATE suppliers SET supplier_number=?,normalized_supplier_number=?,name=?,legal_name=?,tax_id=?,tax_country_code=?,registration_number=?,email=?,phone=?,website=?,default_currency=?,payment_terms_days=?,default_lead_time_days=?,notes=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=? AND status<>'ARCHIVED'",number(c.supplierNumber),number(c.supplierNumber),req(c.name,200),trim(c.legalName,200),trim(c.taxId,64),country(c.taxCountryCode),trim(c.registrationNumber,64),email(c.email),trim(c.phone,40),trim(c.website,500),currency(c.defaultCurrency),days(c.paymentTermsDays),days(c.defaultLeadTimeDays),trim(c.notes,2000),a.tenantId(),id,version);changed(n);audit.record(a,"SUPPLIER_UPDATED","supplier",id.toString());return supplier(a.tenantId(),id);}
 @Transactional Supplier transition(UUID id,String action,long version){var a=manage();Supplier s=supplier(a.tenantId(),id);String next=switch(action){case"activate","unblock"->"ACTIVE";case"deactivate"->"INACTIVE";case"block"->"BLOCKED";case"archive"->"ARCHIVED";default->throw err("INVALID_SUPPLIER_TRANSITION","Unsupported transition");};boolean ok=switch(s.status){case"DRAFT"->Set.of("ACTIVE","ARCHIVED").contains(next);case"ACTIVE"->Set.of("INACTIVE","BLOCKED").contains(next);case"INACTIVE"->Set.of("ACTIVE","BLOCKED","ARCHIVED").contains(next);case"BLOCKED"->Set.of("ACTIVE","ARCHIVED").contains(next);default->false;};if(!ok)throw err("INVALID_SUPPLIER_TRANSITION","Invalid supplier transition");changed(db.update("UPDATE suppliers SET status=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=?",next,a.tenantId(),id,version));String event=switch(action){case"activate"->"SUPPLIER_ACTIVATED";case"deactivate"->"SUPPLIER_DEACTIVATED";case"block"->"SUPPLIER_BLOCKED";case"unblock"->"SUPPLIER_UNBLOCKED";case"archive"->"SUPPLIER_ARCHIVED";default->throw new IllegalStateException();};audit.record(a,event,"supplier",id.toString());if(next.equals("ACTIVE"))events.publishEvent(new ProcurementEvents.SupplierActivated(a.tenantId(),id));if(next.equals("BLOCKED"))events.publishEvent(new ProcurementEvents.SupplierBlocked(a.tenantId(),id));return supplier(a.tenantId(),id);}
 @Transactional(readOnly=true)Supplier detail(UUID id){var a=read();return supplier(a.tenantId(),id);}@Transactional(readOnly=true)List<Supplier>suppliers(String q,String status,String country,String number,int page,int size,String sort){var a=read();page(page,size);String order=switch(sort==null?"name":sort){case"name"->"name";case"supplierNumber"->"normalized_supplier_number";case"status"->"status";case"createdAt"->"created_at";default->throw err("INVALID_SORT","Unsupported sort");};String like=q==null?null:"%"+q.trim().toLowerCase()+"%";return db.query("SELECT id FROM suppliers WHERE tenant_id=? AND (?::text IS NULL OR status=?::text) AND (?::text IS NULL OR tax_country_code=?::text) AND (?::text IS NULL OR normalized_supplier_number=?::text) AND (?::text IS NULL OR lower(name) LIKE ? OR lower(COALESCE(legal_name,'')) LIKE ? OR lower(normalized_supplier_number) LIKE ?) ORDER BY "+order+",id OFFSET ? LIMIT ?",(r,n)->supplier(a.tenantId(),(UUID)r.getObject(1)),a.tenantId(),status,status,country(country),country(country),number==null?null:number(number),number==null?null:number(number),like,like,like,like,page*size,size);}
 @Transactional Address addressCreate(UUID supplierId,AddressCommand c){var a=manage();supplier(a.tenantId(),supplierId);validateAddress(c);UUID id=UUID.randomUUID();db.update("INSERT INTO supplier_addresses(id,tenant_id,supplier_id,type,label,address_line1,address_line2,postal_code,city,state_region,country_code,is_primary,status,created_at,updated_at,version)VALUES(?,?,?,?,?,?,?,?,?,?,?,false,'ACTIVE',now(),now(),0)",id,a.tenantId(),supplierId,c.type,trim(c.label,120),req(c.line1,200),trim(c.line2,200),req(c.postalCode,24),req(c.city,120),trim(c.stateRegion,120),country(c.countryCode));audit.record(a,"SUPPLIER_ADDRESS_CREATED","supplier-address",id.toString());return address(a.tenantId(),id);}@Transactional Address addressUpdate(UUID id,AddressCommand c,long version){var a=manage();validateAddress(c);changed(db.update("UPDATE supplier_addresses SET type=?,label=?,address_line1=?,address_line2=?,postal_code=?,city=?,state_region=?,country_code=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=? AND status='ACTIVE'",c.type,trim(c.label,120),req(c.line1,200),trim(c.line2,200),req(c.postalCode,24),req(c.city,120),trim(c.stateRegion,120),country(c.countryCode),a.tenantId(),id,version));audit.record(a,"SUPPLIER_ADDRESS_UPDATED","supplier-address",id.toString());return address(a.tenantId(),id);}@Transactional Address addressPrimary(UUID id,long version){var a=manage();Address x=address(a.tenantId(),id);if(x.primary)return x;db.update("UPDATE supplier_addresses SET is_primary=false,updated_at=now(),version=version+1 WHERE tenant_id=? AND supplier_id=? AND type=? AND id<>? AND is_primary",a.tenantId(),x.supplierId,x.type,id);changed(db.update("UPDATE supplier_addresses SET is_primary=true,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=? AND status='ACTIVE'",a.tenantId(),id,version));audit.record(a,"SUPPLIER_PRIMARY_ADDRESS_CHANGED","supplier-address",id.toString());return address(a.tenantId(),id);}@Transactional Address addressArchive(UUID id,long version){var a=manage();changed(db.update("UPDATE supplier_addresses SET status='ARCHIVED',is_primary=false,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=?",a.tenantId(),id,version));audit.record(a,"SUPPLIER_ADDRESS_ARCHIVED","supplier-address",id.toString());return address(a.tenantId(),id);}
 @Transactional Contact contactCreate(UUID supplierId,ContactCommand c){var a=manage();supplier(a.tenantId(),supplierId);validateContact(c);UUID id=UUID.randomUUID();db.update("INSERT INTO supplier_contacts(id,tenant_id,supplier_id,first_name,last_name,job_title,email,phone,role,is_primary,active,created_at,updated_at,version)VALUES(?,?,?,?,?,?,?,?,?,false,true,now(),now(),0)",id,a.tenantId(),supplierId,req(c.firstName,120),req(c.lastName,120),trim(c.jobTitle,120),email(c.email),trim(c.phone,40),role(c.role));audit.record(a,"SUPPLIER_CONTACT_CREATED","supplier-contact",id.toString());return contact(a.tenantId(),id);}@Transactional Contact contactUpdate(UUID id,ContactCommand c,long version){var a=manage();validateContact(c);changed(db.update("UPDATE supplier_contacts SET first_name=?,last_name=?,job_title=?,email=?,phone=?,role=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=? AND active",req(c.firstName,120),req(c.lastName,120),trim(c.jobTitle,120),email(c.email),trim(c.phone,40),role(c.role),a.tenantId(),id,version));audit.record(a,"SUPPLIER_CONTACT_UPDATED","supplier-contact",id.toString());return contact(a.tenantId(),id);}@Transactional Contact contactPrimary(UUID id,long version){var a=manage();Contact x=contact(a.tenantId(),id);if(x.primary)return x;db.update("UPDATE supplier_contacts SET is_primary=false,updated_at=now(),version=version+1 WHERE tenant_id=? AND supplier_id=? AND role=? AND id<>? AND is_primary",a.tenantId(),x.supplierId,x.role,id);changed(db.update("UPDATE supplier_contacts SET is_primary=true,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=? AND active",a.tenantId(),id,version));audit.record(a,"SUPPLIER_PRIMARY_CONTACT_CHANGED","supplier-contact",id.toString());return contact(a.tenantId(),id);}@Transactional Contact contactDeactivate(UUID id,long version){var a=manage();changed(db.update("UPDATE supplier_contacts SET active=false,is_primary=false,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=?",a.tenantId(),id,version));audit.record(a,"SUPPLIER_CONTACT_DEACTIVATED","supplier-contact",id.toString());return contact(a.tenantId(),id);}
 @Transactional SupplierProduct productCreate(UUID supplierId,ProductCommand c){var a=manage();supplier(a.tenantId(),supplierId);var variant=catalog.findInventoryVariant(a.tenantId(),c.variantId).orElseThrow(()->err("INVALID_SUPPLIER_PRODUCT_VARIANT","Variant not found"));if("ARCHIVED".equals(variant.status()))throw err("INVALID_SUPPLIER_PRODUCT_VARIANT","Archived variant cannot be mapped");validateProduct(c);UUID id=UUID.randomUUID();try{db.update("INSERT INTO supplier_products(id,tenant_id,supplier_id,variant_id,supplier_sku,normalized_supplier_sku,supplier_product_name,purchase_unit_code,base_units_per_purchase_unit,minimum_order_quantity,order_multiple,unit_cost,currency,lead_time_days,preferred,active,created_at,updated_at,version)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,false,true,now(),now(),0)",id,a.tenantId(),supplierId,c.variantId,sku(c.supplierSku),sku(c.supplierSku),trim(c.name,200),unit(c.purchaseUnitCode),decimal(c.baseUnitsPerPurchaseUnit,true,"INVALID_PURCHASE_UNIT"),decimal(c.minimumOrderQuantity,true,"INVALID_MINIMUM_ORDER_QUANTITY"),decimal(c.orderMultiple,true,"INVALID_ORDER_MULTIPLE"),decimal(c.unitCost,false,"INVALID_UNIT_COST"),currency(c.currency),days(c.leadTimeDays));}catch(Exception e){throw conflict(e,"SUPPLIER_PRODUCT_EXISTS","Supplier product or SKU exists");}audit.record(a,"SUPPLIER_PRODUCT_CREATED","supplier-product",id.toString());events.publishEvent(new ProcurementEvents.SupplierProductCreated(a.tenantId(),id,c.variantId));return product(a.tenantId(),id);}
 @Transactional SupplierProduct productUpdate(UUID id,ProductCommand c,long version){var a=manage();SupplierProduct old=product(a.tenantId(),id);if(!old.variantId.equals(c.variantId))throw err("INVALID_SUPPLIER_PRODUCT_VARIANT","Variant ownership is immutable");validateProduct(c);changed(db.update("UPDATE supplier_products SET supplier_sku=?,normalized_supplier_sku=?,supplier_product_name=?,purchase_unit_code=?,base_units_per_purchase_unit=?,minimum_order_quantity=?,order_multiple=?,unit_cost=?,currency=?,lead_time_days=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=?",sku(c.supplierSku),sku(c.supplierSku),trim(c.name,200),unit(c.purchaseUnitCode),decimal(c.baseUnitsPerPurchaseUnit,true,"INVALID_PURCHASE_UNIT"),decimal(c.minimumOrderQuantity,true,"INVALID_MINIMUM_ORDER_QUANTITY"),decimal(c.orderMultiple,true,"INVALID_ORDER_MULTIPLE"),decimal(c.unitCost,false,"INVALID_UNIT_COST"),currency(c.currency),days(c.leadTimeDays),a.tenantId(),id,version));audit.record(a,"SUPPLIER_PRODUCT_UPDATED","supplier-product",id.toString());return product(a.tenantId(),id);}
 @Transactional SupplierProduct prefer(UUID id,long version){var a=manage();SupplierProduct p=product(a.tenantId(),id);Supplier s=supplier(a.tenantId(),p.supplierId);if(!p.active||!s.status.equals("ACTIVE"))throw err("SUPPLIER_BLOCKED","Only active supplier products may be preferred");try{changed(db.update("UPDATE supplier_products SET preferred=true,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=?",a.tenantId(),id,version));}catch(Exception e){throw conflict(e,"PREFERRED_SUPPLIER_CONFLICT","Another active supplier is preferred");}audit.record(a,"SUPPLIER_PRODUCT_PREFERRED","supplier-product",id.toString());events.publishEvent(new ProcurementEvents.PreferredSupplierChanged(a.tenantId(),p.variantId,id));return product(a.tenantId(),id);}@Transactional SupplierProduct productDeactivate(UUID id,long version){var a=manage();changed(db.update("UPDATE supplier_products SET active=false,preferred=false,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=?",a.tenantId(),id,version));audit.record(a,"SUPPLIER_PRODUCT_DEACTIVATED","supplier-product",id.toString());return product(a.tenantId(),id);}
 @Transactional(readOnly=true)SupplierProduct productDetail(UUID id){var a=read();return product(a.tenantId(),id);}@Transactional(readOnly=true)List<SupplierProduct>products(UUID supplierId,UUID variantId,Boolean active,Boolean preferred,String supplierSku,int page,int size,String sort){var a=read();page(page,size);String order=switch(sort==null?"supplierSku":sort){case"supplierSku"->"normalized_supplier_sku";case"unitCost"->"unit_cost NULLS LAST";case"leadTimeDays"->"lead_time_days NULLS LAST";case"createdAt"->"created_at";default->throw err("INVALID_SORT","Unsupported sort");};return db.query("SELECT id FROM supplier_products WHERE tenant_id=? AND (?::uuid IS NULL OR supplier_id=?::uuid) AND (?::uuid IS NULL OR variant_id=?::uuid) AND (?::boolean IS NULL OR active=?::boolean) AND (?::boolean IS NULL OR preferred=?::boolean) AND (?::text IS NULL OR normalized_supplier_sku=?::text) ORDER BY "+order+",id OFFSET ? LIMIT ?",(r,n)->product(a.tenantId(),(UUID)r.getObject(1)),a.tenantId(),supplierId,supplierId,variantId,variantId,active,active,preferred,preferred,supplierSku==null?null:sku(supplierSku),supplierSku==null?null:sku(supplierSku),page*size,size);}@Transactional(readOnly=true)SupplierProduct lookup(UUID supplierId,String supplierSku){var a=read();var ids=db.query("SELECT id FROM supplier_products WHERE tenant_id=? AND supplier_id=? AND normalized_supplier_sku=?",(r,n)->(UUID)r.getObject(1),a.tenantId(),supplierId,sku(supplierSku));if(ids.isEmpty())throw err("SUPPLIER_PRODUCT_NOT_FOUND","Supplier product not found");return product(a.tenantId(),ids.getFirst());}
 @Override@Transactional(readOnly=true)public Optional<PurchasingParameters>findEligible(UUID tenantId,UUID supplierId,UUID variantId){return eligibility("p.tenant_id=? AND p.supplier_id=? AND p.variant_id=?",tenantId,supplierId,variantId);}@Override@Transactional(readOnly=true)public Optional<PurchasingParameters>findEligibleProduct(UUID tenantId,UUID supplierProductId){return eligibility("p.tenant_id=? AND p.id=?",tenantId,supplierProductId);}private Optional<PurchasingParameters>eligibility(String predicate,Object...args){return db.query("SELECT p.id,p.supplier_id,p.variant_id,p.supplier_sku,p.purchase_unit_code,p.base_units_per_purchase_unit,p.minimum_order_quantity,p.order_multiple,p.unit_cost,p.currency,COALESCE(p.lead_time_days,s.default_lead_time_days) FROM supplier_products p JOIN suppliers s ON s.tenant_id=p.tenant_id AND s.id=p.supplier_id WHERE "+predicate+" AND p.active AND s.status='ACTIVE'",(r,n)->new PurchasingParameters((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getBigDecimal(8),r.getBigDecimal(9),r.getString(10),(Integer)r.getObject(11)),args).stream().findFirst();}
 private AuthorizationService.Access read(){return auth.require(Permission.PROCUREMENT_SUPPLIER_READ);}private AuthorizationService.Access manage(){return auth.require(Permission.PROCUREMENT_SUPPLIER_MANAGE);}private Supplier supplier(UUID t,UUID id){var x=db.query("SELECT id,supplier_number,name,legal_name,status,tax_id,tax_country_code,registration_number,email,phone,website,default_currency,payment_terms_days,default_lead_time_days,notes,created_at,updated_at,version FROM suppliers WHERE tenant_id=? AND id=?",(r,n)->new Supplier((UUID)r.getObject(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10),r.getString(11),r.getString(12),(Integer)r.getObject(13),(Integer)r.getObject(14),r.getString(15),r.getTimestamp(16).toInstant(),r.getTimestamp(17).toInstant(),r.getLong(18)),t,id);if(x.isEmpty())throw err("SUPPLIER_NOT_FOUND","Supplier not found");return x.getFirst();}private Address address(UUID t,UUID id){var x=db.query("SELECT id,supplier_id,type,label,address_line1,address_line2,postal_code,city,state_region,country_code,is_primary,status,created_at,updated_at,version FROM supplier_addresses WHERE tenant_id=? AND id=?",(r,n)->new Address((UUID)r.getObject(1),(UUID)r.getObject(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10),r.getBoolean(11),r.getString(12),r.getTimestamp(13).toInstant(),r.getTimestamp(14).toInstant(),r.getLong(15)),t,id);if(x.isEmpty())throw err("SUPPLIER_ADDRESS_NOT_FOUND","Supplier address not found");return x.getFirst();}private Contact contact(UUID t,UUID id){var x=db.query("SELECT id,supplier_id,first_name,last_name,job_title,email,phone,role,is_primary,active,created_at,updated_at,version FROM supplier_contacts WHERE tenant_id=? AND id=?",(r,n)->new Contact((UUID)r.getObject(1),(UUID)r.getObject(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getBoolean(9),r.getBoolean(10),r.getTimestamp(11).toInstant(),r.getTimestamp(12).toInstant(),r.getLong(13)),t,id);if(x.isEmpty())throw err("SUPPLIER_CONTACT_NOT_FOUND","Supplier contact not found");return x.getFirst();}private SupplierProduct product(UUID t,UUID id){var x=db.query("SELECT id,supplier_id,variant_id,supplier_sku,supplier_product_name,purchase_unit_code,base_units_per_purchase_unit,minimum_order_quantity,order_multiple,unit_cost,currency,lead_time_days,preferred,active,created_at,updated_at,version FROM supplier_products WHERE tenant_id=? AND id=?",(r,n)->new SupplierProduct((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),r.getString(4),r.getString(5),r.getString(6),r.getBigDecimal(7),r.getBigDecimal(8),r.getBigDecimal(9),r.getBigDecimal(10),r.getString(11),(Integer)r.getObject(12),r.getBoolean(13),r.getBoolean(14),r.getTimestamp(15).toInstant(),r.getTimestamp(16).toInstant(),r.getLong(17)),t,id);if(x.isEmpty())throw err("SUPPLIER_PRODUCT_NOT_FOUND","Supplier product not found");return x.getFirst();}
 private static void page(int p,int s){if(p<0||s<1||s>100)throw err("INVALID_PAGINATION","Invalid pagination");}private static String req(String x,int max){String y=trim(x,max);if(y==null||y.isBlank())throw err("INVALID_PROCUREMENT_DATA","Required value missing");return y;}private static String trim(String x,int max){if(x==null)return null;String y=x.trim();if(y.length()>max)throw err("INVALID_PROCUREMENT_DATA","Value too long");return y.isEmpty()?null:y;}private static String number(String x){String y=req(x,40).toUpperCase(Locale.ROOT).replaceAll("\\s+","-");if(!y.matches("[A-Z0-9][A-Z0-9._/-]{1,39}"))throw err("INVALID_SUPPLIER_NUMBER","Invalid supplier number");return y;}private static String sku(String x){return req(x,128).toUpperCase(Locale.ROOT).replaceAll("\\s+","-");}private static String country(String x){if(x==null)return null;String y=x.trim().toUpperCase(Locale.ROOT);if(!y.matches("[A-Z]{2}"))throw err("INVALID_COUNTRY_CODE","ISO alpha-2 country required");return y;}private static String currency(String x){try{return Currency.getInstance(req(x,3).toUpperCase(Locale.ROOT)).getCurrencyCode();}catch(Exception e){throw err("INVALID_CURRENCY","ISO 4217 currency required");}}private static String email(String x){String y=trim(x,254);if(y!=null&&!y.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))throw err("INVALID_EMAIL","Invalid email");return y;}private static String role(String x){String y=req(x,16).toUpperCase(Locale.ROOT);if(!Set.of("SALES","ORDERING","LOGISTICS","ACCOUNTS","QUALITY","GENERAL").contains(y))throw err("INVALID_CONTACT_ROLE","Invalid contact role");return y;}private static String unit(String x){String y=req(x,8).toUpperCase(Locale.ROOT);if(!y.matches("[A-Z0-9]{1,8}"))throw err("INVALID_PURCHASE_UNIT","Invalid purchase unit");return y;}private static Integer days(Integer x){if(x!=null&&(x<0||x>3650))throw err("INVALID_LEAD_TIME","Days out of range");return x;}private static BigDecimal decimal(String x,boolean positive,String code){if(x==null)return null;try{BigDecimal v=new BigDecimal(x).setScale(6,RoundingMode.UNNECESSARY);if(positive?v.signum()<=0:v.signum()<0)throw new Exception();return v;}catch(Exception e){throw err(code,"Invalid exact decimal");}}private static void validateSupplier(SupplierCommand c){currency(c.defaultCurrency);days(c.paymentTermsDays);days(c.defaultLeadTimeDays);}private static void validateAddress(AddressCommand c){if(!Set.of("REGISTERED","ORDERING","SHIPPING","BILLING","RETURNS","OTHER").contains(c.type))throw err("INVALID_ADDRESS_TYPE","Invalid address type");country(c.countryCode);}private static void validateContact(ContactCommand c){if(email(c.email)==null&&trim(c.phone,40)==null)throw err("INVALID_CONTACT","Email or phone required");role(c.role);}private static void validateProduct(ProductCommand c){decimal(c.baseUnitsPerPurchaseUnit,true,"INVALID_PURCHASE_UNIT");decimal(c.minimumOrderQuantity,true,"INVALID_MINIMUM_ORDER_QUANTITY");decimal(c.orderMultiple,true,"INVALID_ORDER_MULTIPLE");decimal(c.unitCost,false,"INVALID_UNIT_COST");currency(c.currency);days(c.leadTimeDays);}private static void changed(int n){if(n!=1)throw err("CONCURRENT_MODIFICATION","Record was modified");}private static RuntimeException conflict(Exception e,String code,String message){if(e instanceof ProcurementException p)return p;return err(code,message);}private static ProcurementException err(String c,String m){return new ProcurementException(c,m);}
 record SupplierCommand(String supplierNumber,String name,String legalName,String taxId,String taxCountryCode,String registrationNumber,String email,String phone,String website,String defaultCurrency,Integer paymentTermsDays,Integer defaultLeadTimeDays,String notes){}record AddressCommand(String type,String label,String line1,String line2,String postalCode,String city,String stateRegion,String countryCode){}record ContactCommand(String firstName,String lastName,String jobTitle,String email,String phone,String role){}record ProductCommand(UUID variantId,String supplierSku,String name,String purchaseUnitCode,String baseUnitsPerPurchaseUnit,String minimumOrderQuantity,String orderMultiple,String unitCost,String currency,Integer leadTimeDays){}record Supplier(UUID id,String supplierNumber,String name,String legalName,String status,String taxId,String taxCountryCode,String registrationNumber,String email,String phone,String website,String defaultCurrency,Integer paymentTermsDays,Integer defaultLeadTimeDays,String notes,Instant createdAt,Instant updatedAt,long version){}record Address(UUID id,UUID supplierId,String type,String label,String addressLine1,String addressLine2,String postalCode,String city,String stateRegion,String countryCode,boolean primary,String status,Instant createdAt,Instant updatedAt,long version){}record Contact(UUID id,UUID supplierId,String firstName,String lastName,String jobTitle,String email,String phone,String role,boolean primary,boolean active,Instant createdAt,Instant updatedAt,long version){}record SupplierProduct(UUID id,UUID supplierId,UUID variantId,String supplierSku,String supplierProductName,String purchaseUnitCode,BigDecimal baseUnitsPerPurchaseUnit,BigDecimal minimumOrderQuantity,BigDecimal orderMultiple,BigDecimal unitCost,String currency,Integer leadTimeDays,boolean preferred,boolean active,Instant createdAt,Instant updatedAt,long version){}
}
